from itertools import combinations
import random

# Fixed edges that must be present
fixed_edges = [(1,3), (2,7), (3,11), (3,10), (0,12), (2,10), (2,4), (1,11)]

# All possible edges
all_edges = [(u, v) for u in range(13) for v in range(u+1, 13)]

# Check if a set of edges forms a clique of size > 5
def has_large_clique(edges, max_clique_size=5):
    # Build adjacency
    adj = {i: set() for i in range(13)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check all subsets of size max_clique_size+1
    for subset in combinations(range(13), max_clique_size + 1):
        is_clique = True
        for i in range(len(subset)):
            for j in range(i+1, len(subset)):
                if subset[j] not in adj[subset[i]]:
                    is_clique = False
                    break
            if not is_clique:
                break
        if is_clique:
            return True
    return False

# Check chromatic number using greedy coloring (upper bound)
def chromatic_number(edges):
    adj = {i: set() for i in range(13)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Try to find coloring with k colors
    def can_color(k):
        colors = [-1] * 13
        def backtrack(v):
            if v == 13:
                return True
            for c in range(k):
                valid = True
                for neighbor in adj[v]:
                    if neighbor < v and colors[neighbor] == c:
                        valid = False
                        break
                if valid:
                    colors[v] = c
                    if backtrack(v + 1):
                        return True
                    colors[v] = -1
            return False
        return backtrack(0)

    for k in range(1, 14):
        if can_color(k):
            return k
    return 13

# Check minimum degree
def min_degree(edges):
    deg = [0] * 13
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
    return min(deg)

# Start with fixed edges
current_edges = set(fixed_edges)

# Check current state
print("Fixed edges:", len(current_edges))
print("Min degree with fixed edges:", min_degree(list(current_edges)))

# We need to add more edges to ensure min degree >= 4
# Let's use a greedy approach

def solve():
    # Start with fixed edges
    edges = set(fixed_edges)

    # Calculate current degrees
    deg = [0] * 13
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1

    # Add edges to satisfy min degree constraint
    # Try different orderings
    random.seed(42)

    for attempt in range(1000):
        edges = set(fixed_edges)
        deg = [0] * 13
        for u, v in edges:
            deg[u] += 1
            deg[v] += 1

        # Add edges greedily
        candidates = [e for e in all_edges if e not in edges]
        random.shuffle(candidates)

        for u, v in candidates:
            if deg[u] < 4 or deg[v] < 4:
                edges.add((u, v))
                deg[u] += 1
                deg[v] += 1

        # Check if all degrees >= 4
        if min(deg) < 4:
            continue

        # Check clique constraint
        if has_large_clique(list(edges)):
            continue

        # Check chromatic number
        chi = chromatic_number(list(edges))
        if chi > 5:
            continue

        print(f"Found solution on attempt {attempt}")
        print(f"Number of edges: {len(edges)}")
        print(f"Min degree: {min(deg)}")
        print(f"Chromatic number: {chi}")
        return list(edges)

    return None

result = solve()
if result:
    print("Solution found!")
    print(sorted(result))
else:
    print("No solution found with greedy approach")

